CREATE TABLE IF NOT EXISTS training_courses (id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT DEFAULT '',level TEXT DEFAULT 'Basic',duration_hours INTEGER DEFAULT 1,active INTEGER DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS training_enrollments (id TEXT PRIMARY KEY,course_id TEXT NOT NULL,user_id TEXT NOT NULL,status TEXT DEFAULT 'Enrolled',progress INTEGER DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(course_id,user_id),FOREIGN KEY(course_id) REFERENCES training_courses(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
